INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('2c5b86ab-7a42-4126-a793-ed4bbd6ddd75', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Foundation — company overview', 'Foundation is an Ohio pre-seed venture that 3D-prints the formwork for residential concrete foundations — printing the wall shape directly and eliminating the traditional build-strip-repair-clean formwork cycle. On a typical 2,100 sq ft single-family Ohio home it cuts foundation formwork labor from ~336 hours to ~25 and total formwork cost by ~47% (≈11 days saved). Stage: pre-seed, TRL 6–7.', NULL, 'Ohio pre-seed venture that 3D-prints residential foundation formwork; ~47% formwork cost + ~11 days saved on a 2,100 sq ft home.', 59, 393, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.406Z'::timestamptz, '2026-07-31T23:25:08.406Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('094a9bdf-8a8b-4e20-9f3e-ad8e15686e10', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Technology overview — print process + differentiators', 'A build plan is downloaded to the printer; concrete is pumped into the machine and the nozzle lays it one layer at a time. A printing trolley moves laterally and vertically while the whole machine travels along runway rails; the system is electrically powered. Two differentiators: it uses common, locally sourced concrete (not a proprietary mortar), and an external gate controls material flow at the nozzle. Net: eliminates the build-strip-repair-clean cycle, ~311 labor hrs/home saved, ~47–50% lower production cost and ~60–65% lower material cost vs mortar-based printers.', NULL, 'Downloads plan → pumps concrete → lays layers; trolley moves lat/vert on rails; electric. Uses common local concrete (not mortar); external nozzle gate.', 87, 576, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.414Z'::timestamptz, '2026-07-31T23:25:08.414Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('743308d4-2b6a-4052-89f4-a2aebfa6d50f', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Market — TAM/SAM/SOM + formwork wedge', 'The 2026 U.S. housing market is a $410B TAM against a ~500,000-home supply/demand gap; "locked-in" 6% mortgages push builders toward new-build "buy-down" economics. Foundation targets the formwork line item of single-family new builds — a $23.7B SAM — with a near-term $27.4M SOM in its regional beachhead. Foundation 3D printing lowers total home cost ~4% while removing the most labor-intensive, waste-prone step.', NULL, 'TAM $410B (2026 housing), SAM $23.7B (SF-newbuild formwork), SOM $27.4M; ~500k supply gap; foundation 3D printing cuts total home cost ~4%.', 62, 415, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.421Z'::timestamptz, '2026-07-31T23:25:08.421Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('dc7439bd-a48b-4f6e-887b-01715f0f31bc', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Competitive analysis — vs Traditional / Vitruvian / COBOD', 'Across Time, Deployment, Material Accessibility, Project Costs, Scalability, and Repeatable Workflow, Foundation wins where adoption is decided. Traditional formwork is slow and labor-heavy; Vitruvian and COBOD depend on costly proprietary mortar and lack local-material accessibility and lowest project cost. Foundation uniquely combines local-material accessibility and lowest project cost with rapid, scalable, repeatable deployment.', NULL, 'Foundation is the only option combining local-material accessibility + lowest project cost with rapid, scalable, repeatable deployment.', 53, 436, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.427Z'::timestamptz, '2026-07-31T23:25:08.427Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('4e83b078-9f26-4c9c-9512-e23960837737', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Development stage & timeline (TRL 6–7)', 'The technology is at TRL 6–7: delivery, nozzle-gate, and gantry-motion subsystems are demonstrated; the team is building a beta prototype for a relevant application environment. MVP customer requirements: rapid deployment, reduced labor, structural reliability, and locally sourced materials. A 14-month plan spans Grants+Funding, Product R&D, Beta Prototype, Design Finalization, Third-Party Performance Validation, and First Printer Build.', NULL, 'TRL 6–7; beta prototype in progress; 14-month Gantt through third-party validation + first printer build. MVP: rapid deploy, reduced labor, structural reliability, local materials.', 56, 441, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 0, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.433Z'::timestamptz, '2026-07-31T23:25:08.433Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('b043a57a-ccff-4b57-9676-96a108d5ac44', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Project plan & milestones', 'Milestones: (1) Hire core team, Months 1–2, $10k; (2) R&D with Converge — engineer the beta printer + delivery/gate, Months 3–4, $190k; (3) Beta prototype build, Months 6–8; (4) Third-party performance validation — independent structural + throughput test, Months 9–14, ~$30k; (5) First printer build — production-representative unit for pilots, Months 11–14, ~$300k (blended grant/VC).', NULL, 'Hire (Mo1-2 $10k) → R&D w/ Converge (Mo3-4 $190k) → beta prototype (Mo6-8) → third-party validation (Mo9-14 $30k) → first printer build (Mo11-14 $300k).', 55, 386, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 13, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.450Z'::timestamptz, '2026-08-01T00:55:39.650Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('a7fe2453-3121-42f6-a67e-0f606fd2c565', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Budget basis — TVSF $200k by spend type', 'TVSF request is $200,000 of OTF Project Funds: Personnel $40,000 (founding-team time + first technical hire), Equipment $120,000 (COTS + specialized printer/delivery parts for the beta prototype), Supplies $10,000 (concrete + consumables for prototype tests), Purchased Services $30,000 (Converge development services + a software-development partner). Total $200,000.', NULL, 'Personnel $40k, Equipment $120k, Supplies $10k, Purchased Services $30k = $200k. Bulk = equipment (COTS+parts) + Converge services.', 47, 368, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 13, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.462Z'::timestamptz, '2026-08-01T00:55:39.650Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('680bd643-c69b-4876-8396-1c551c3535db', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Team / management', 'Kate Ulepic (CEO) leads strategy and fundraising; Conor Atkins (COO) owns operations and print execution; Connor Casey (CFO) owns finance and the capital plan; Will Curley (CTO) owns the printer and delivery technology. Known gaps being recruited: legal advisor, fundraiser, technician, and homebuilder partner. Mentored through the Entrepreneurs’ Center (Paul Jackson, VP Strategic Programs).', NULL, 'Kate Ulepic CEO, Conor Atkins COO, Connor Casey CFO, Will Curley CTO. Gaps: legal advisor, fundraiser, technician, homebuilder. EC-mentored (Paul Jackson).', 54, 393, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 13, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.456Z'::timestamptz, '2026-08-01T00:55:39.650Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('6d236196-a5ac-48e5-8ba9-73e9876c9517', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Intellectual property — 2 issued patents', 'Foundation is anchored by two issued U.S. patents: 11,273,574 ("Scalable Three-Dimensional Printing Apparatus") covering the scalable gantry/print architecture, and 10,307,959 B2 ("Concrete Delivery System") covering the concrete-delivery and nozzle-control mechanism — protecting the rail-scalable printer and the externally gated, local-concrete delivery path.', NULL, 'U.S. Patents 11,273,574 (Scalable 3D Printing Apparatus) and 10,307,959 B2 (Concrete Delivery System).', 42, 362, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 13, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.439Z'::timestamptz, '2026-08-01T00:55:39.650Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO library_atoms (id, tenant_id, grain, title, content, canvas_nodes, summary, word_count, char_count, member_summary, status, confidence, outcome, outcome_score, usage_count, source, cocoon_id, origin_proposal_id, origin_section_id, embedding, owner_user_id, visibility, created_at, updated_at, creator_kind, created_by, source_anchor, vault_id) VALUES ('f14e550f-4e85-49ed-bffb-7910b3ed7b81', '17780cad-76c0-4cef-95ec-2a536bcf5c8f', 'primitive', 'Business model & financials', 'Foundation forms a joint venture per project, programs and prepares the print, and charges per cubic yard of concrete placed — ≈$20,000 per job at ≈37.5% contribution margin ("printing as a service"). The capital plan pairs $200k TVSF and $150k SBIR Phase I (non-dilutive, for R&D + the beta prototype) with a targeted $1.8M+ equity round; the grants de-risk the technology and prove the market so the equity round is priced on validated performance.', NULL, 'JV per project; charge per cubic yard; ≈$20k/job; ≈37.5% contribution margin. Raise: $200k TVSF + $150k SBIR + $1.8M+ equity; pre-seed.', 74, 450, '{}'::jsonb, 'approved', 0.5, 'pending', 0.5, 13, 'upload', NULL, NULL, NULL, NULL, NULL, 'tenant', '2026-07-31T23:25:08.444Z'::timestamptz, '2026-08-01T00:55:39.650Z'::timestamptz, 'admin', 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL) ON CONFLICT DO NOTHING;
