INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('9be7dd8e-0368-4c52-ad88-4a52b749c8e4', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '6', '#5 Intellectual Property', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n19","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#5  Intellectual Property"}},{"id":"n20","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation''s approach is anchored by two issued U.S. patents:"}},{"id":"n21","type":"bulleted_list","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"items":[{"text":"U.S. Patent 11,273,574 — \"Scalable Three-Dimensional Printing Apparatus\" (the scalable gantry/print architecture)."},{"text":"U.S. Patent 10,307,959 B2 — \"Concrete Delivery System\" (the concrete-delivery and nozzle-control mechanism)."}]}},{"id":"n22","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Together they protect the two core differentiators — the rail-scalable printer and the externally gated, local-concrete delivery path. Freedom-to-operate and a continuation strategy around the nozzle-gate control are part of the funded work."}}],"metadata":{"title":"#5 Intellectual Property","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.495Z'::timestamptz, true, '2026-08-01T00:55:39.495Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('e43e02fd-798b-4d46-a95f-1e158ce67704', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '3', '#2 Overview of the Technology', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n8","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#2  Overview of the Technology"}},{"id":"n9","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation''s system prints a foundation''s wall geometry directly: a build plan is downloaded to the printer, concrete is pumped into the machine, and the nozzle lays concrete one layer at a time. A printing trolley moves laterally and vertically while the whole machine travels along runway rails; the system is electrically powered."}},{"id":"n10","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Two differentiators define it:"}},{"id":"n11","type":"bulleted_list","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"items":[{"text":"It uses common, locally sourced concrete — not an expensive proprietary mortar."},{"text":"An external gate controls material flow at the nozzle, enabling clean starts/stops and consistent layers."}]}},{"id":"n12","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"The net effect eliminates the build-strip-repair-clean cycle, saving ~311 labor hours per home and cutting formwork production cost ~47–50% and material cost ~60–65% versus mortar-based concrete printers."}}],"metadata":{"title":"#2 Overview of the Technology","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.330Z'::timestamptz, true, '2026-08-01T00:55:39.330Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('6248f6f0-c399-45ad-94c4-a749351fe548', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '7', '#6 Business Model & Pro-forma P&L', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n23","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#6  Business Model & Pro-forma P&L"}},{"id":"n24","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation forms a joint venture per project, programs and prepares the print, and charges per cubic yard of concrete placed, at ≈$20,000 total price per job with a contribution margin of ≈37.5%. Printing-as-a-service keeps capital with Foundation and lowers the builder''s barrier to adoption."}},{"id":"n25","type":"table","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"headers":["Pro-forma (per job, illustrative)","Value"],"rows":[["Price per job","$20,000"],["Contribution margin","≈37.5%"],["Contribution per job","$7,500"]],"header_style":{"bold":true,"bg":"#D9E1F2","alignment":"center"},"sheet_name":"Proforma"}},{"id":"n26","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Against a $27.4M near-term SOM, a modest fleet of printers running repeat jobs reaches sustainable unit economics quickly; gross margin expands as printer utilization rises."}}],"metadata":{"title":"#6 Business Model & Pro-forma P&L","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', 1, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.542Z'::timestamptz, true, '2026-08-01T00:55:39.542Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('09a649a6-a401-4be8-bd32-d63bc05c0e0f', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '12', '#11 Project Plan (milestones)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n40","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#11  Project Plan"}},{"id":"n41","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Milestones (name · description · success criteria · timeframe · approximate funds):"}},{"id":"n42","type":"table","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"headers":["#","Milestone","Success criteria","Timeframe","Funds"],"rows":[["1","Hire core team","Technician/operator roles filled","Months 1–2","$10,000"],["2","R&D with Converge","Validated printer + delivery/gate specs","Months 3–4","$190,000"],["3","Beta prototype build","Prints a test wall to spec","Months 6–8","(in R&D)"],["4","Third-party validation","Passing structural + throughput report","Months 9–14","$30,000"],["5","First printer build","Pilot-ready production unit","Months 11–14","$300,000"]],"header_style":{"bold":true,"bg":"#D9E1F2","alignment":"center"},"sheet_name":"ProjectPlan"}}],"metadata":{"title":"#11 Project Plan (milestones)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.146Z'::timestamptz, true, '2026-08-01T00:55:39.146Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('59101536-8ea6-4940-917d-439af55d1456', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '8', '#7 Financial Stage (capital plan)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n27","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#7  Current Financial Stage & Fundraising"}},{"id":"n28","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation is pre-seed. The capital plan pairs $200k TVSF and $150k SBIR Phase I (non-dilutive, directed at R&D and the beta prototype) with a targeted $1.8M+ equity round."}},{"id":"n29","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Equity investment is critical to scaling beyond the first printer; the non-dilutive grants exist to prove the market and de-risk the technology first, so the equity raise is priced on validated performance rather than on a concept. TVSF is the near-term unlock for the validated beta prototype that makes the round investable."}}],"metadata":{"title":"#7 Financial Stage (capital plan)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.590Z'::timestamptz, true, '2026-08-01T00:55:39.590Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('15e0ab02-5857-463a-b63f-5abca7627709', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '13', '#12 Budget by spend type (Personnel/Equipment/Supplies/Purchased Services → OTF Project Funds + Total)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n43","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#12  Budget by Spend Type"}},{"id":"n44","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"TVSF request: $200,000 of OTF Project Funds."}},{"id":"n45","type":"table","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"headers":["Spend type","OTF Project Funds","Notes"],"rows":[["Personnel","$40,000","Founding-team time + first technical hire"],["Equipment","$120,000","COTS + specialized printer/delivery parts (beta prototype)"],["Supplies","$10,000","Concrete + consumables for prototype tests"],["Purchased Services","$30,000","Converge development services + software partner"],["TOTAL","$200,000",""]],"header_style":{"bold":true,"bg":"#D9E1F2","alignment":"center"},"sheet_name":"Budget"}},{"id":"n46","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Narrative: the bulk of the grant funds Equipment (COTS + specialized parts to build the beta prototype with Converge) and Purchased Services (Converge engineering + software partner); Supplies cover concrete for prototype testing; Personnel covers founding-team time and the first technical hire."}}],"metadata":{"title":"#12 Budget by spend type (Personnel/Equipment/Supplies/Purchased Services → OTF Project Funds + Total)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.197Z'::timestamptz, true, '2026-08-01T00:55:39.197Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Budget', 2, NULL, '{}', '{"itemType":"spreadsheet","volumeName":"Budget","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'eb5ce2be-ae34-4e0d-a0da-11cb3b9f0418') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('290800ef-4593-4391-8778-7afed4fe8685', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '10', '#9 Competitive Landscape', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n33","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#9  Competitive Landscape"}},{"id":"n34","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Against Traditional Formwork, Vitruvian, and COBOD International, Foundation wins on the dimensions that decide adoption:"}},{"id":"n35","type":"table","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"headers":["Dimension","Foundation","Traditional","Vitruvian","COBOD"],"rows":[["Time (days)","✓","✗","✓","✓"],["Deployment","✓","✗","✓","✗"],["Material accessibility","✓","✓","✗","✗"],["Project costs","✓","✗","✗","✗"],["Scalability","✓","✗","✓","✓"],["Repeatable workflow","✓","✗","✓","✓"]],"header_style":{"bold":true,"bg":"#D9E1F2","alignment":"center"},"sheet_name":"Competitive"}},{"id":"n36","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation is the only option that combines local-material accessibility and lowest project cost with rapid, scalable, repeatable deployment — traditional formwork is slow and labor-heavy, while other printers depend on costly proprietary mortar."}}],"metadata":{"title":"#9 Competitive Landscape","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.018Z'::timestamptz, true, '2026-08-01T00:55:39.018Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('31151c5f-8815-4b49-a014-0031642ca494', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '2', '#1 Market Opportunity (TAM)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n4","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#1  Market Opportunity (TAM)"}},{"id":"n5","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"The 2026 U.S. housing market represents a $410B TAM against a structural ~500,000-home supply/demand gap; \"locked-in\" 6% mortgages push builders toward new-build \"buy-down\" economics where every point of cost removed matters. Foundation targets the formwork line item of single-family new builds — a $23.7B SAM — with an initial serviceable-obtainable $27.4M SOM in its regional beachhead."}},{"id":"n6","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Because foundation 3D printing lowers total home cost ~4% while removing the industry''s most labor-intensive, waste-prone step, it converts a cost center into a competitive advantage for builders operating on thin margins."}},{"id":"n7","type":"table","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"headers":["Market layer","Size","Definition"],"rows":[["TAM","$410B","2026 U.S. housing market"],["SAM","$23.7B","Formwork in single-family new builds"],["SOM","$27.4M","Near-term regional beachhead"]],"header_style":{"bold":true,"bg":"#D9E1F2","alignment":"center"},"sheet_name":"Market"}}],"metadata":{"title":"#1 Market Opportunity (TAM)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.269Z'::timestamptz, true, '2026-08-01T00:55:39.269Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('5e481833-a9c5-4d39-a6c5-1139825fea22', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '1', 'Abstract (public, non-confidential; excluded from the 7-page limit)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n1","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"Abstract"}},{"id":"n2","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"(Public, non-confidential — excluded from the 7-page limit.)","inline_formats":[{"start":0,"length":42,"format":"italic"}]}},{"id":"n3","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation is an Ohio pre-seed venture that 3D-prints the formwork for residential concrete foundations. By printing the foundation wall shape directly — with common, locally sourced concrete rather than proprietary mortar — Foundation eliminates the traditional build-strip-repair-clean formwork cycle, cutting foundation formwork labor from ~336 hours to ~25 and total formwork cost by roughly 47% on a typical 2,100 sq ft Ohio home. TVSF funds a beta prototype and third-party performance validation, de-risking a $23.7B U.S. formwork market and advancing Ohio''s housing-affordability and advanced-manufacturing agenda."}}],"metadata":{"title":"Abstract (public, non-confidential; excluded from the 7-page limit)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:38.939Z'::timestamptz, true, '2026-08-01T00:55:38.939Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('cf21afa9-4da3-499f-aba9-6cd9cba4cb2c', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '11', '#10 Economic Impact (Ohio)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n37","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#10  Economic Impact (Ohio)"}},{"id":"n38","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Foundation is Ohio-based and Ohio-building. It lowers the cost of new single-family homes in a state facing a supply gap, supports builder margins, and creates skilled advanced-manufacturing and print-operator jobs."}},{"id":"n39","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"By partnering with local schools and builders for demos and training, it seeds a regional workforce pipeline and keeps concrete spend with local suppliers rather than proprietary-mortar vendors — compounding the in-state economic return of each job."}}],"metadata":{"title":"#10 Economic Impact (Ohio)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.086Z'::timestamptz, true, '2026-08-01T00:55:39.086Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('49c7d43f-aa70-4029-ba84-78c45f6f125f', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '4', '#3 Development Stage', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n13","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#3  Development Stage"}},{"id":"n14","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"The technology is at TRL 6–7: core subsystems (concrete delivery, nozzle gate, gantry motion) are demonstrated and the team is building a beta prototype for a relevant application environment. MVP customer requirements are explicit — rapid deployment, reduced labor, structural reliability, and use of locally sourced materials."}},{"id":"n15","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"TVSF''s role is to fund the beta prototype build and an independent third-party performance validation, moving the system from demonstrated subsystems (TRL 6–7) toward a field-validated first printer (TRL 7–8)."}}],"metadata":{"title":"#3 Development Stage","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.387Z'::timestamptz, true, '2026-08-01T00:55:39.387Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id) VALUES ('d8e0d38e-de1f-4ac0-80bb-acd9e4c4b4bd', 'c3db60b1-2f0e-4bc8-903c-1ec098906c58', '5', '#4 Commercialization Strategy (SAM)', '{"version":1,"document_id":"00000000-0000-0000-0000-000000000000","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation   ·   Ohio Third Frontier TVSF (Round 45)","height":28,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":28,"font":{"family":"Times New Roman","size":8}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":7,"max_slides":null},"nodes":[{"id":"n16","type":"heading","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"level":1,"text":"#4  Commercialization Strategy (SAM)"}},{"id":"n17","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"Entry is proof-based: local, fragmented buyers whose barriers are trust, portability, and cost, and whose workflow already relies on subcontractors. Foundation sells into that workflow as \"printing as a service\" to general contractors and developers, priced per cubic yard of concrete, and partners with local schools and builders for demos and workforce pipeline."}},{"id":"n18","type":"text_block","style":{},"history":[],"library_eligible":true,"provenance":{"source":"manual"},"content":{"text":"The motion is demos/tours → paid pilot → repeat jobs, using non-dilutive TVSF + SBIR Phase I to reach a validated pilot before scaling into the $23.7B formwork SAM."}}],"metadata":{"title":"#4 Commercialization Strategy (SAM)","volume_id":"","required_item_id":"","proposal_id":"c3db60b1-2f0e-4bc8-903c-1ec098906c58","solicitation_id":"","created_at":"2026-07-31T00:00:00Z","last_modified_at":"2026-07-31T00:00:00Z","last_modified_by":"","version_number":1,"status":"complete"}}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-01T00:53:38.306Z'::timestamptz, '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-01T00:55:44.852Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-01T00:55:39.439Z'::timestamptz, true, '2026-08-01T00:55:39.439Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null,"sourceAtomIds":["a7fe2453-3121-42f6-a67e-0f606fd2c565","680bd643-c69b-4876-8396-1c551c3535db","b043a57a-ccff-4b57-9676-96a108d5ac44","f14e550f-4e85-49ed-bffb-7910b3ed7b81","6d236196-a5ac-48e5-8ba9-73e9876c9517"]}'::jsonb, 'e4fd5e12-2ad1-4e1e-9ac0-2c534d0583d7') ON CONFLICT DO NOTHING;
